import RNA
import random
import sys
import multiprocessing as mp
import math
import time

TARGET = "((..(((..((((..((....((..((((....))....))..))))..))....))..))((..((..((..((((..((....((..((((..((....((....))))..))....))..))))..))((..((..((....))((..((((..((....((..((((....))....))..))))..))....))..))))..))..))..))((..((....((..((((..((....((....))))..))....))..))))..))))..))..)..))"
N = len(TARGET)

def pairs_from_db(db):
    stack = []
    pairs = [-1] * len(db)
    for i, c in enumerate(db):
        if c == '(':
            stack.append(i)
        elif c == ')':
            j = stack.pop()
            pairs[i] = j
            pairs[j] = i
    return pairs

TARGET_PAIRS = pairs_from_db(TARGET)
PAIR_LIST = [(i, j) for i, j in enumerate(TARGET_PAIRS) if j != -1 and i < j]
UNPAIRED = [i for i in range(N) if TARGET_PAIRS[i] == -1]
POS_TO_PAIRIDX = {}
for idx, (i, j) in enumerate(PAIR_LIST):
    POS_TO_PAIRIDX[i] = idx
    POS_TO_PAIRIDX[j] = idx

BASES = "ACGU"
PAIR_OPTIONS = [("G","C"), ("C","G"), ("A","U"), ("U","A"), ("G","U"), ("U","G")]
STRONG_PAIR_OPTIONS = [("G","C"), ("C","G")]

def random_seq_init(rng, gc_bias=0.5):
    seq = [None] * N
    for i, j in PAIR_LIST:
        if rng.random() < gc_bias:
            a, b = rng.choice(STRONG_PAIR_OPTIONS)
        else:
            a, b = rng.choice(PAIR_OPTIONS)
        seq[i] = a
        seq[j] = b
    for i in UNPAIRED:
        seq[i] = rng.choice("AAAUC")
    return seq

def fold(seq_str):
    fc = RNA.fold_compound(seq_str)
    mfe_struct, mfe = fc.mfe()
    return mfe_struct

def bp_dist_from_struct(mfe_struct):
    return RNA.bp_distance(mfe_struct, TARGET)

def diff_positions(mfe_struct):
    mfe_pairs = pairs_from_db(mfe_struct)
    diff = []
    for i in range(N):
        if mfe_pairs[i] != TARGET_PAIRS[i]:
            diff.append(i)
    return diff, mfe_pairs

def targeted_mutate(seq, rng, diff_positions_list):
    seq = seq[:]
    if not diff_positions_list:
        return seq
    pos = rng.choice(diff_positions_list)
    if pos in POS_TO_PAIRIDX:
        i, j = PAIR_LIST[POS_TO_PAIRIDX[pos]]
        if rng.random() < 0.75:
            a, b = rng.choice(STRONG_PAIR_OPTIONS)
        else:
            a, b = rng.choice(PAIR_OPTIONS)
        seq[i] = a
        seq[j] = b
    else:
        seq[pos] = rng.choice(BASES)
    return seq

def random_mutate(seq, rng):
    seq = seq[:]
    r = rng.random()
    if r < 0.6 and PAIR_LIST:
        i, j = rng.choice(PAIR_LIST)
        a, b = rng.choice(PAIR_OPTIONS)
        seq[i] = a
        seq[j] = b
    else:
        if UNPAIRED:
            k = rng.choice(UNPAIRED)
            seq[k] = rng.choice(BASES)
    return seq

def anneal(seed, steps):
    rng = random.Random(seed)
    seq = random_seq_init(rng, gc_bias=rng.uniform(0.3, 0.8))
    seq_str = "".join(seq)
    struct = fold(seq_str)
    cur_dist = bp_dist_from_struct(struct)
    best_dist = cur_dist
    best_seq = seq_str
    cur_seq = seq

    T0 = 1.5
    T1 = 0.02
    stall = 0
    for step in range(steps):
        T = T0 * ((T1 / T0) ** (step / steps))
        diff, mfe_pairs = diff_positions(struct)
        if rng.random() < 0.85 and diff:
            new_seq = targeted_mutate(cur_seq, rng, diff)
        else:
            new_seq = random_mutate(cur_seq, rng)
        new_seq_str = "".join(new_seq)
        new_struct = fold(new_seq_str)
        dist = bp_dist_from_struct(new_struct)
        delta = dist - cur_dist
        if delta <= 0 or rng.random() < math.exp(-delta / max(T, 1e-6)):
            cur_seq = new_seq
            cur_dist = dist
            struct = new_struct
            if dist < best_dist:
                best_dist = dist
                best_seq = new_seq_str
                stall = 0
                if best_dist == 0:
                    break
            else:
                stall += 1
        else:
            stall += 1
        if stall > 400:
            # restart from best with perturbation
            cur_seq = list(best_seq)
            for _ in range(5):
                cur_seq = random_mutate(cur_seq, rng)
            seq_str2 = "".join(cur_seq)
            struct = fold(seq_str2)
            cur_dist = bp_dist_from_struct(struct)
            stall = 0
    return best_seq, best_dist

def worker(args):
    seed, steps = args
    try:
        seq, dist = anneal(seed, steps)
        return (seed, seq, dist)
    except Exception as e:
        return (seed, None, 9999)

if __name__ == "__main__":
    n_workers = int(sys.argv[1]) if len(sys.argv) > 1 else 200
    steps = int(sys.argv[2]) if len(sys.argv) > 2 else 3000
    t0 = time.time()
    with mp.Pool(min(n_workers, mp.cpu_count())) as pool:
        results = pool.map(worker, [(i, steps) for i in range(n_workers)])
    results.sort(key=lambda x: x[2])
    print("TIME", time.time() - t0)
    for seed, seq, dist in results[:15]:
        print(dist, seed, seq)
    best = results[0]
    with open("/tmp/rna_best2.txt", "w") as f:
        f.write(f"{best[2]}\n{best[1]}\n")

